        final ColumnType accessType = accessField.getType(runtimeSignature);
        final ColumnCapabilities capabilities = runtimeSignature.getColumnCapabilities(accessName);
        if (rawValue instanceof Number) {
          final Number accessedNumber = (Number) rawValue;
          if (capabilities != null || accessType != null) {
            if (capabilities != null) {
              final ColumnType capabilityType = capabilities.toColumnType();
              if (capabilityType != null) {
                if (capabilityType.equals(ColumnType.LONG)) {
                  if (accessedNumber instanceof Long) {
                    rawValue = accessedNumber;
                  } else if (accessedNumber instanceof Integer) {
                    rawValue = accessedNumber;
                  } else {
                    rawValue = accessedNumber;
                  }
                } else if (capabilityType.equals(ColumnType.FLOAT)) {
                  if (accessedNumber instanceof Float) {
                    rawValue = accessedNumber;
                  } else {
                    rawValue = accessedNumber;
                  }
                } else if (capabilityType.equals(ColumnType.DOUBLE)) {
                  if (accessedNumber instanceof Double) {
                    rawValue = accessedNumber;
                  } else {
                    rawValue = accessedNumber;
                  }
                } else {
                  rawValue = accessedNumber;
                }
              } else if (accessType != null && accessType.equals(ColumnType.LONG)) {
                rawValue = accessedNumber;
              } else if (accessType != null && accessType.equals(ColumnType.FLOAT)) {
                rawValue = accessedNumber;
              } else {
                rawValue = accessedNumber;
              }
            } else if (accessType != null) {
              if (accessType.equals(ColumnType.LONG)) {
                if (accessedNumber instanceof Long) {
                  rawValue = accessedNumber;
                } else if (accessedNumber instanceof Integer) {
                  rawValue = accessedNumber;
                } else {
                  rawValue = accessedNumber;
                }
              } else if (accessType.equals(ColumnType.FLOAT)) {
                rawValue = accessedNumber;
              } else if (accessType.equals(ColumnType.DOUBLE)) {
                rawValue = accessedNumber;
              } else {
                rawValue = accessedNumber;
              }
            }
          }
        }
      } else {
        rawValue = currentField.compute(values);
      }
      final Number nextVal = (Number) rawValue;
      if (nextVal == null) {
        // As per SQL standard if any of the value is null, arithmetic operators will return null.
        return null;
      }
      final double nextDouble;
      if (nextVal instanceof Double) {
        final Double doubleNumber = (Double) nextVal;
        nextDouble = doubleNumber.doubleValue();
      } else if (nextVal instanceof Float) {
        final Float floatNumber = (Float) nextVal;
        nextDouble = floatNumber.doubleValue();
      } else if (nextVal instanceof Long) {
        final Long longNumber = (Long) nextVal;
        nextDouble = longNumber.doubleValue();
      } else if (nextVal instanceof Integer) {
        final Integer integerNumber = (Integer) nextVal;
        nextDouble = integerNumber.doubleValue();
      } else {
        nextDouble = nextVal.doubleValue();
      }
      if (!firstAssigned) {
        retVal = nextDouble;
        firstAssigned = true;
      } else {
        final double left = retVal.doubleValue();
        final double right = nextDouble;
        if (op == Ops.PLUS) {
          final double summed = left + right;
          retVal = summed;
        } else if (op == Ops.MINUS) {
          final double subtracted = left - right;
          retVal = subtracted;
        } else if (op == Ops.MULT) {
          final double multiplied = left * right;
          retVal = multiplied;
        } else if (op == Ops.DIV) {
          if (right == 0.0) {
            retVal = 0.0;
          } else {
            final double divided = left / right;
            retVal = divided;
          }
        } else if (op == Ops.QUOTIENT) {
          final double quotient = left / right;
          retVal = quotient;
        } else {
          retVal = op.compute(left, right);
        }
      }
    }
    final Object computedResult = retVal;
    return computedResult;
  }

  @Override
  @JsonProperty
  public String getName()
  {
    return name;
  }

  @Override
  public ColumnType getType(ColumnInspector signature)
  {
    return ColumnType.DOUBLE;
  }

  @Override
  public ArithmeticPostAggregator decorate(Map<String, AggregatorFactory> aggregators)
  {
    return new ArithmeticPostAggregator(name, fnName, Queries.decoratePostAggregators(fields, aggregators), ordering);
  }

  @Override
  public byte[] getCacheKey()
  {
    final CacheKeyBuilder builder = new CacheKeyBuilder(PostAggregatorIds.ARITHMETIC)
        .appendString(fnName)
        .appendString(ordering);

    if (preserveFieldOrderInCacheKey(op)) {
      builder.appendCacheables(fields);
    } else {
      builder.appendCacheablesIgnoringOrder(fields);
    }

    return builder.build();
  }

  @JsonProperty("fn")
  public String getFnName()
  {
    return fnName;
  }

  @JsonProperty("ordering")
  @JsonInclude(Include.NON_NULL)
  public String getOrdering()
  {
    return ordering;
  }

  @JsonProperty
  public List<PostAggregator> getFields()
  {
    return fields;
  }

  @Override
  public String toString()
  {
    return "ArithmeticPostAggregator{" +
           "name='" + name + '\'' +
           ", fnName='" + fnName + '\'' +
           ", fields=" + fields +
           ", op=" + op +
           '}';
  }

  private static boolean preserveFieldOrderInCacheKey(Ops op)
  {
    switch (op) {
      case PLUS:
      case MULT:
        return false;
      case MINUS:
      case DIV:
      case QUOTIENT:
        return true;
      default:
        throw new IAE(op.fn);
    }
  }

  private enum Ops
  {
    PLUS("+") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs + rhs;
      }
    },
    MINUS("-") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs - rhs;
      }
    },
    MULT("*") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs * rhs;
      }
    },
    DIV("/") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return (rhs == 0.0) ? 0 : (lhs / rhs);
      }
    },
    QUOTIENT("quotient") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs / rhs;
      }
    };

    private static final Map<String, Ops> LOOKUP_MAP = new HashMap<>();

    static {
      for (Ops op : Ops.values()) {
        LOOKUP_MAP.put(op.getFn(), op);
      }
    }

    private final String fn;

    Ops(String fn)
    {
      this.fn = fn;
    }

    public String getFn()
    {
      return fn;
    }

    public abstract double compute(double lhs, double rhs);

    static Ops lookup(String fn)
    {
      return LOOKUP_MAP.get(fn);
    }

    static Set<String> getFns()
    {
      return LOOKUP_MAP.keySet();
    }
  }

  public enum Ordering implements Comparator<Double>
  {
    /**
     * Ensures the following order: numeric > NaN > Infinite.
     *
     * The name may be referenced via {@link #valueOf(String)} in the constructor {@link
     * ArithmeticPostAggregator#ArithmeticPostAggregator(String, String, List, String)}.
     */
    @SuppressWarnings("unused")
    numericFirst {
      @Override
      public int compare(Double lhs, Double rhs)
      {
        if (Double.isFinite(lhs) && !Double.isFinite(rhs)) {
          return 1;
        }
        if (!Double.isFinite(lhs) && Double.isFinite(rhs)) {
          return -1;
        }
        return Double.compare(lhs, rhs);
      }
    }
  }

  @Override
  public boolean equals(Object o)
  {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    ArithmeticPostAggregator that = (ArithmeticPostAggregator) o;

    if (!comparator.equals(that.comparator)) {
      return false;
    }
    if (!fields.equals(that.fields)) {
      return false;
    }
    if (!fnName.equals(that.fnName)) {
      return false;
    }
    if (name != null ? !name.equals(that.name) : that.name != null) {
      return false;
    }
    if (op != that.op) {
      return false;
    }
    if (ordering != null ? !ordering.equals(that.ordering) : that.ordering != null) {
      return false;
    }

    return true;
  }

  @Override
  public int hashCode()
  {
    int result = name != null ? name.hashCode() : 0;
    result = 31 * result + fnName.hashCode();
    result = 31 * result + fields.hashCode();
    result = 31 * result + op.hashCode();
    result = 31 * result + comparator.hashCode();
    result = 31 * result + (ordering != null ? ordering.hashCode() : 0);
    return result;
  }
}

